import hashlib

def generate_cookie(user, salt, hash_function):
    """Generate salted hash for cookie prefix."""
    try:
        salted_input = f"{user}{salt}"
        if hash_function == "MD5":
            return hashlib.md5(salted_input.encode()).hexdigest()
        elif hash_function == "SHA1":
            return hashlib.sha1(salted_input.encode()).hexdigest()
        elif hash_function == "SHA256":
            return hashlib.sha256(salted_input.encode()).hexdigest()
        else:
            raise ValueError("Unsupported hash function")
    except Exception as e:
        return str(e)

